import itertools

def find_cycle_price(N):
    # Generate all possible permutations of the cycle
    for perm in itertools.permutations(range(1, N)):
        # Create the adjacency matrix for the cycle
        matrix = [[0] * N for _ in range(N)]
        for i in range(N):
            matrix[i][(i + 1) % N] = perm[i]
            matrix[(i + 1) % N][i] = perm[i]

        # Check if all edges are distinct and within the limit
        edges = set()
        for i in range(N):
            for j in range(i + 1, N):
                if matrix[i][j] != 0:
                    edges.add(matrix[i][j])

        if len(edges) == N * (N - 1) // 2 and max(edges) <= 1000:
            return matrix

